import { getDistance, getDistanceByNum, NVector3 } from '../../../../../../../lib';
import { APolygonGraphWrapper } from '..';
export class InteractionComponent {
  public geo: APolygonGraphWrapper;
  public xOff = 5;
  public yOff = 5;
  private showPopupStackTimer: NodeJS.Timer | number;
  constructor(geo: APolygonGraphWrapper) {
    this.geo = geo;
  }
  public isMouseInside(x: number, y: number): boolean {
    if (this.geo.graphCore.isMouseInside(x, y) !== -1) {
      return true;
    }

    if (
      this.geo.scene.annotationInstance.geometryCommon.gcmdProcessing.isMouseInsideByOffScreen(
        x  - this.geo.scene.paramsEditing.croppingMaskParams.x,
        y  - this.geo.scene.paramsEditing.croppingMaskParams.y,
        this.geo.hashColor
      )
    ) {
      return true;
    }
    return false;
  }
  public GetLog() {
    if (this.geo.isRemove || !this.geo.isRenderable || this.geo.isHiddenValue) {
      return '';
    }
    const text =
      'GUID : ' +
      this.geo.id +
      '/' +
      'TYPE : ' +
      this.geo.type.toString() +
      '/' +
      // 'PARENT : ' + this.geo.edges[0].GetParentType()+'<br>'+
      // 'Geo : ' + 'lat:' + this.geo.geoVec.x.toFixed(5).toString() + ', Log:' + this.geo.geoVec.y.toFixed(5).toString() + '/' +
      'Screen : ' +
      // this.geo.vec.ToString() +
      '/' +
      'pos : ' +
      this.geo.graphCore.vs.length +
      '/' +
      'Area : ' +
      this.geo.getArea().toFixed(3).toString() +
      ' m2' +
      '/' +
      // 'STYLE : ' + this.geo.style.toString() + '/' +
      // 'CONNE :' + this.geo.edges.length.toString() + '/' +
      'IsSEL : ' +
      this.geo.isSelectedValue +
      '/' +
      'isSelable : ' +
      this.geo.isSelectable;
    return text;
  }
  public hide(): void {
    //
  }
  public showPopupSummary() {
    if (!this.geo.scene.annotationInstance.activeCommandController.needPopup()) {
      return
    }
    // console.trace();
    // console.log('pop');
    if (this.geo.hasPopup || this.geo.isGhost) {
      return;
    }
    // if (this.geo.isGhost) { return; }
    this.geo.hasPopup = true;

    this.geo.popup = document.createElement('div') as HTMLDivElement;
    this.geo.popup.id = 'pa-' + this.geo.id;
    this.geo.popup.style.position = 'absolute';
    this.geo.popup.style.zIndex = '1000';
    this.geo.popup.style.height = '0px';
    this.geo.popup.style.width = '0px';
    this.geo.popup.style.backgroundColor = 'red';
    this.geo.scene.annotationInstance.implementations.app.model.modelViewWrapper.div.appendChild(
      this.geo.popup
    );
    this.geo.popup.style.top = this.geo.vec.y + 'px';
    this.geo.popup.style.left = this.geo.vec.x + 'px';

    if (this.showPopupStackTimer) {
      // @ts-ignore
      clearTimeout(this.showPopupStackTimer as NodeJS.Timer);
    }
    this.showPopupStackTimer = setTimeout(() => {
      if (this.geo.popup) {
        this.geo.scene.annotationInstance.io.eventListenerAnnotation.showPopupStack(
          this.geo.toJSON()
        );
      }
    }, this.geo.timePopupDelay);
  }
  public needSnapping(v: NVector3) {
    let dis = 15;
    let theDis = dis;
    let temp: NVector3 = new NVector3(-100, -100);

    for (let i = 0; i < this.geo.graphCore.vs.length - 1; ++i) {
      theDis = getDistance(this.geo.graphCore.vs[i], v);
      if (theDis < dis) {
        dis = theDis;
        temp = this.geo.graphCore.vs[i];
      }

      theDis = getDistanceByNum(
        v.x,
        v.y,
        this.geo.graphCore.vs[i + 1].x - this.geo.graphCore.vs[i].x,
        this.geo.graphCore.vs[i + 1].y - this.geo.graphCore.vs[i].y
      );
      if (theDis < dis) {
        dis = theDis;
        temp.x = this.geo.graphCore.vs[i + 1].x - this.geo.graphCore.vs[i].x;
        temp.y = this.geo.graphCore.vs[i + 1].y - this.geo.graphCore.vs[i].y;
      }
    }
    theDis = getDistance(this.geo.graphCore.vs[this.geo.graphCore.vs.length - 1], v);
    if (theDis < dis) {
      dis = theDis;
      temp = this.geo.graphCore.vs[this.geo.graphCore.vs.length - 1];
    }
    theDis = getDistanceByNum(
      v.x,
      v.y,
      this.geo.graphCore.vs[this.geo.graphCore.vs.length - 1].x - this.geo.graphCore.vs[0].x,
      this.geo.graphCore.vs[this.geo.graphCore.vs.length - 1].y - this.geo.graphCore.vs[0].y
    );
    if (theDis < dis) {
      dis = theDis;
      temp.x =
        this.geo.graphCore.vs[this.geo.graphCore.vs.length - 1].x - this.geo.graphCore.vs[0].x;
      temp.y =
        this.geo.graphCore.vs[this.geo.graphCore.vs.length - 1].y - this.geo.graphCore.vs[0].y;
    }

    return [dis, temp];
  }
}
