  public checkAttachedTextleaderline(g: AGeometryBase) {
    if (g.type === GType.POLYGON_GRAPH) {
      const pGraph = g as APolygonGraphWrapper;
      return pGraph.checkAttachedTextleaderline();
    } else if (g.type === GType.POLYLINE_BENDING) {
      const pLineGraph = g as APolylineGraphWrapper;
      return pLineGraph.checkAttachedTextleaderline();
    } else if (g.type === GType.RECTANGLE) {
      const rect = g as ARectangleWrapper;
      return rect.checkAttachedTextleaderline();
    } else if (g.type === GType.CIRCLE) {
      const cir = g as ACircleWrapper;
      return cir.CheckAttachedTextleaderline();
    }

    //  for RPoint NPoint Nodes
    if (g.textLeaderline && g.textLeaderline.leaderline) {
      if (getDistance(g.textLeaderline.leaderline.v2, g.vec) > 5) {
        g.textLeaderline.attachedShape = undefined;
        g.textLeaderline = undefined;
        return false;
      }
    }
    return true;
  }

