  public isMouseInsideByOffScreenNumberPoint(x: number, y: number, colTarget: number[]) {
    // const col = this.gcmd.annotationInstance.implementations.app.model.graphicsCoreWrapper.canvasWrapper.aCanvasOffScreen.GetColorByPos(x, y);
    const col = this.pickColorsOffscreen(x, y, 3 , 3);
    const tolerance = 30
    if (
      getColorDistance(col[0], col[1], col[2], colTarget[0], colTarget[1], colTarget[2]) < tolerance ||
      getColorDistance(col[0+4], col[1+4], col[2+4], colTarget[0], colTarget[1], colTarget[2]) < tolerance ||
      getColorDistance(col[0+(4*2)], col[1+(4*2)], col[2+(4*2)], colTarget[0], colTarget[1], colTarget[2]) < tolerance ||
      getColorDistance(col[0+(4*3)], col[1+(4*3)], col[2+(4*3)], colTarget[0], colTarget[1], colTarget[2]) < tolerance ||
      getColorDistance(col[0+(4*4)], col[1+(4*4)], col[2+(4*4)], colTarget[0], colTarget[1], colTarget[2]) < tolerance ||
      getColorDistance(col[0+(4*5)], col[1+(4*5)], col[2+(4*5)], colTarget[0], colTarget[1], colTarget[2]) < tolerance ||
      getColorDistance(col[0+(4*6)], col[1+(4*6)], col[2+(4*6)], colTarget[0], colTarget[1], colTarget[2]) < tolerance ||
      getColorDistance(col[0+(4*7)], col[1+(4*7)], col[2+(4*7)], colTarget[0], colTarget[1], colTarget[2]) < tolerance ||
      getColorDistance(col[0+(4*8)], col[1+(4*8)], col[2+(4*8)], colTarget[0], colTarget[1], colTarget[2]) < tolerance
    ) {
      return true;
    }
    return false;
  }
  public isMouseInsideByOffScreen(x: number, y: number, c: string) {
    // const col = this.gcmd.annotationInstance.implementations.app.model.graphicsCoreWrapper.canvasWrapper.aCanvasOffScreen.GetColorByPos(x, y);
    const col = this.pickColorOffscreen(x, y);
    const shape = this.getShapeByHashCol(col);
    if (shape && col === c) {
      return true;
    }
    return false;
  }

  public getClosestNodeForSnapping(x: number, y: number, tor: number): AGeometryBase | undefined {
    const mv = new NVector3(x, y);
    let i = this.gcmd.annotationInstance.scene.listBasePoint.length;
    let theIndex = -1;
    while (i--) {
      if (this.gcmd.annotationInstance.scene.listBasePoint[i].isCollapse) {
        continue;
      }

      // only allow to snap for the mid point of arrow, not the polyline bending
      if (this.gcmd.annotationInstance.scene.listBasePoint[i].type === GType.AMIDPOINT) {
        const point = this.gcmd.annotationInstance.scene.listBasePoint[i] as APoint;
        if (point.aEdges[0] && point.aEdges[0].pGraph.type === GType.POLYLINE_BENDING) {
          continue;
        }
      }

      const dis = getDistance(this.gcmd.annotationInstance.scene.listBasePoint[i].vec, mv);
      if (dis < tor) {
        tor = dis;
        theIndex = i;
      }
    }

    // ...... snap to rectangle and circle
    i = this.gcmd.annotationInstance.scene.listARectangleWrapper.length;
    while (i--) {
      const shape = this.gcmd.annotationInstance.scene.listARectangleWrapper[i];
      shape.updateLeaderlineSnap(mv, tor);
      if (shape.vecSelectedSnapping) {
        if (getDistance(shape.vecSelectedSnapping, mv) < 5) {
          return shape;
        }
        shape.vecSelectedSnapping = undefined;
      }
    }
    i = this.gcmd.annotationInstance.scene.listACircleWrapperr.length;
    while (i--) {
      const shape = this.gcmd.annotationInstance.scene.listACircleWrapperr[i];
      shape.updateLeaderlineSnap(mv, tor);
      if (shape.vecSelectedSnapping) {
        if (getDistance(shape.vecSelectedSnapping, mv) < 5) {
          return shape;
        }
        shape.vecSelectedSnapping = undefined;
      }
    }
    // ...... end snap to rectangle and circle

    if (theIndex > -1) {
      return this.gcmd.annotationInstance.scene.listBasePoint[theIndex] as AGeometryBase;
    }
    i = this.gcmd.annotationInstance.scene.listAPolygonGraphWrapper.length;
    while (i--) {
      const pg = this.gcmd.annotationInstance.scene.listAPolygonGraphWrapper[i].getclosestNode(
        mv,
        tor
      );
      if (pg) {
        return pg as AGeometryBase;
      }
    }
    return undefined;
  }
