  public duplicateByDragging() {
    // console.log('copy needed');
    if (this.gcmd.annotationInstance.scene.Capture) {
      const geo = this.gcmd.annotationInstance.scene.Capture.deepCopy(
        this.gcmd.annotationInstance.scene.Capture.vec.x,
        this.gcmd.annotationInstance.scene.Capture.vec.y
      );
      this.gcmd.annotationInstance.scene.Capture.isHover = false;
      this.gcmd.annotationInstance.scene.Capture.isSelected = false;
      if (geo) {
        geo.isHover = true;
        this.gcmd.annotationInstance.scene.Capture = geo;
      }
    }
    const geos = this.hasMultiSel();
    if (geos !== undefined) {
      for (const theGeo of geos) {
        // if (theGeo.IsCaptured) { continue; }
        theGeo.isSelected = false;
        theGeo.isHover = false;
        const g = theGeo.deepCopy(theGeo.vec.x, theGeo.vec.y);
        if (g) {
          g.isSelected = true;
          g.isHover = true;
        }
      }
    }
  }
  public getSelectedGeoIDs() {
    const geo = [];
    for (let i = 0; i < this.gcmd.annotationInstance.scene.geometryList.length; ++i) {
      if (
        this.gcmd.annotationInstance.scene.geometryList[i].type === GType.ANODE_RECT ||
        this.gcmd.annotationInstance.scene.geometryList[i].type === GType.ANODE_CIRCLE
      ) {
        continue;
      }
      if (this.gcmd.annotationInstance.scene.geometryList[i].isSelectedValue) {
        geo.push(this.gcmd.annotationInstance.scene.geometryList[i].id);
      }
    }
    return geo;
  }
  public processingUpdate(id: string, data: string) {
    const geo = this.getGeoById(id);
    if (geo && geo.type === GType.TEXT_LEADERLINE) {
      const txt = geo as ATextleaderlineWrapper;
      txt.processingUpdate(data);
    }
  }
  public removeByIDs(ids: string) {
    const ioGeos: IOGeometry[] = [];
    JSON.parse(ids).forEach((id: string) => {
      const shape = this.getGeoById(id);
      if (shape) {
        const ioGeo = shape.toJSON();
        if (ioGeo) {
          ioGeos.push(ioGeo);
          shape.remove(false); // we are going to emit them at once below!!
        }
      }
    });
    this.gcmd.annotationInstance.io.eventListenerAnnotation.removeGeometryStack(ioGeos);
    this.gcmd.gcmdSupporting.renderForce();
  }
  public removeBeforeDump() {
    this.gcmd.gcmdSelecting.deSelectAllObjects();
    this.removeAllCapturedGeo();
    let i = this.gcmd.annotationInstance.scene.listATextleaderlineWrapper.length;
    while (i--) {
      if (this.gcmd.annotationInstance.scene.listATextleaderlineWrapper[i]) {
        this.gcmd.annotationInstance.scene.listATextleaderlineWrapper[i].removeDiv();
      }
    }

    this.removeAllDiv();
    this.resetGeometryList();
  }
  public reUndoProcessing(states: IOGeometry[]) {
    this.removeBeforeDump();

    states.forEach((geo: IOGeometry) => {
      this.getGeoByIOGeometry(geo, true);
    });

    this.initConnectionTextleaderlines();
    this.gcmd.annotationInstance.activeCommandController.acProperties.needExecuteOptimizer = true;
    this.gcmd.gcmdSupporting.renderForce();
  }
