  public getPosBySnapping(x: number, y: number, tolerance: number) {
    let dis = 15; // Number.MAX_SAFE_INTEGER;
    let tempTarget = new NVector3(x, y);
    const temp = new NVector3(x, y);
    let i = this.gcmd.annotationInstance.scene.geometryList.length;
    while (i--) {
      const theDis = this.gcmd.annotationInstance.scene.geometryList[i].needSnapping(temp);
      // @ts-ignore
      if (theDis[0] && theDis[1] && theDis[0] > 0 && theDis[0] < dis) {
        dis = theDis[0] as number;
        tempTarget = theDis[1] as NVector3;
      }
    }
    if (dis < tolerance) {
      x = tempTarget.x;
      y = tempTarget.y;
    }
    return [x, y];
  }
