  public getGeoByIOGeometry(geo: IOGeometry, isUndo = false, isDeepCopy = false) {
    if (geo === undefined) {
      return;
    }
    // console.log(geo, isUndo)
    if (geo.type === GType.POINT_REGULAR) {
      APointRegularWrapper.fromJSON(this.gcmd.annotationInstance.scene, geo, isUndo, isDeepCopy);
    } else if (geo.type === GType.POINT_NUMBERED) {
      APointNumberedWrapper.FromJSON(this.gcmd.annotationInstance.scene, geo, isUndo, isDeepCopy);
    } else if (geo.type === GType.CIRCLE) {
      ACircleWrapper.fromJSON(this.gcmd.annotationInstance.scene, geo, isUndo, isDeepCopy);
    } else if (geo.type === GType.RECTANGLE) {
      ARectangleWrapper.fromJSON(this.gcmd.annotationInstance.scene, geo, isUndo, isDeepCopy);
    } else if (geo.type === GType.POLYLINE) {
      APolylineWrapper.fromJSON(this.gcmd.annotationInstance.scene, geo, isUndo, isDeepCopy);
    } else if (geo.type === GType.POLYLINE_BENDING) {
      APolylineGraphWrapper.fromJSON(this.gcmd.annotationInstance.scene, geo, isUndo, isDeepCopy);
    } else if (geo.type === GType.POLYGON) {
      APolygonWrapper.fromJSON(this.gcmd.annotationInstance.scene, geo, isUndo, isDeepCopy);
    } else if (geo.type === GType.POLYGON_GRAPH) {
      APolygonGraphWrapper.fromJSON(this.gcmd.annotationInstance.scene, geo, isUndo, isDeepCopy);
    } else if (geo.type === GType.POINT_ICON) {
      APointIconWrapper.fromJSON(this.gcmd.annotationInstance.scene, geo, isUndo, isDeepCopy);
    } else if (geo.type === GType.ARROW_SINGLE) {
      AArrow.fromJSON(this.gcmd.annotationInstance.scene, geo, isUndo, isDeepCopy, true);
    } else if (geo.type === GType.ARROW_DOUBLE) {
      AArrow.fromJSON(this.gcmd.annotationInstance.scene, geo, isUndo, isDeepCopy, false);
    } else if (geo.type === GType.CURVE_OPEN) {
      ACurve.fromJSON(this.gcmd.annotationInstance.scene, geo, isUndo, isDeepCopy);
    } else if (geo.type === GType.CURVE_CLOSE) {
      ACurve.fromJSON(this.gcmd.annotationInstance.scene, geo, isUndo, isDeepCopy, true);
      // } else if (geo.type === GType.TEXT) {
      //   AText.FromJSON(this.gcmd.annotationInstance.scene, geo, isUndo, isDeepCopy);
    } else if (geo.type === GType.TEXT_LEADERLINE) {
      ATextleaderlineWrapper.fromJSON(this.gcmd.annotationInstance.scene, geo, isUndo, isDeepCopy);
    }
  }
